//! Typed view of `schema/units.json`.
//!
//! Generated by `tools/extract-units.py` from `src/measurement/Unit.cpp`,
//! `src/measurement/UnitSystem.cpp` and `src/measurement/SucroseConversion.cpp`, and embedded at
//! compile time.

use std::collections::BTreeMap;
use std::sync::OnceLock;

use serde::Deserialize;

#[derive(Debug, Clone, Deserialize)]
pub struct UnitData {
    pub generated_by: String,
    pub source_files: Vec<String>,
    pub physical_quantities: Vec<String>,
    pub systems_of_measurement: Vec<String>,
    pub unit_systems: Vec<UnitSystemDef>,
    pub units: Vec<UnitDef>,
    /// Coefficients lowest order first, as `Polynomial() << a << b << …` writes them.
    pub polynomials: BTreeMap<String, Vec<f64>>,
    /// The USDA table: refractive index at 20 °C, degrees Brix, apparent specific gravity 20/20 °C.
    pub sucrose_conversions: Vec<[f64; 3]>,
    pub converted_by_formula: Vec<String>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct UnitDef {
    pub name: String,
    pub unit_system: String,
    /// The abbreviations a user may type, e.g. `°C` and `C`.  The first is the one displayed.
    pub abbreviations: Vec<String>,
    /// Whether what the user typed is rewritten before parsing; only specific gravity does this.
    pub sanitises_input: bool,
    /// The unit this one converts to and from.  `None` means it is itself canonical.
    pub canonical: Option<String>,
    /// How many canonical units one of these is worth.  Meaningless when `converts_by_formula`.
    pub scale: f64,
    /// Set when the C++ converts with a lambda rather than a scale factor; see [`super::formula`].
    pub converts_by_formula: bool,
    /// Above this quantity the display logic prefers the next unit up.
    pub boundary_value: Option<f64>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct UnitSystemDef {
    pub name: String,
    pub physical_quantity: String,
    pub default_unit: String,
    pub unique_name: String,
    pub system_of_measurement: String,
    /// Smallest to largest, the order the display logic steps through.
    pub units: Vec<String>,
    /// The unit used for mash thickness, where this system has one.
    pub thickness: Option<String>,
}

const UNITS_JSON: &str = include_str!(concat!(env!("CARGO_MANIFEST_DIR"), "/../../../schema/units.json"));

/// The unit data, parsed once.
///
/// # Panics
///
/// If the embedded JSON does not match these types, which is a build-time inconsistency between
/// `tools/extract-units.py` and this crate.
pub fn unit_data() -> &'static UnitData {
    static DATA: OnceLock<UnitData> = OnceLock::new();
    DATA.get_or_init(|| {
        serde_json::from_str(UNITS_JSON).expect("schema/units.json does not match bt_measure::UnitData")
    })
}

impl UnitData {
    pub fn unit(&self, name: &str) -> Option<&UnitDef> {
        self.units.iter().find(|unit| unit.name == name)
    }

    pub fn unit_system(&self, name: &str) -> Option<&UnitSystemDef> {
        self.unit_systems.iter().find(|system| system.name == name)
    }

    /// Every unit system that measures `physical_quantity`.
    pub fn systems_for(&self, physical_quantity: &str) -> impl Iterator<Item = &UnitSystemDef> {
        self.unit_systems.iter().filter(move |system| system.physical_quantity == physical_quantity)
    }
}
